import math
def clamp(x,a,b): return max(a,min(b,x))
def interp(points,u):
    p=sorted(points)
    for a,b in zip(p,p[1:]):
        if a[0]<=u<=b[0]:
            f=(u-a[0])/max(0.0001,b[0]-a[0])
            return a[1]+f*(b[1]-a[1])
    return None
def control(obs):
    m=obs['local_map']
    look=6.0
    vals=[]
    for u in [4.0,5.0,6.0,7.0]:
        l=interp(m['left_rail'],u); r=interp(m['right_rail'],u)
        if l is not None and r is not None: vals.append((u,(l+r)/2))
    if vals:
        u,y=min(vals,key=lambda p:abs(p[0]-look))
        k=2*y/(u*u+y*y)
    else:
        k=0.0
    h=obs['hitch_deg']
    hd=clamp(math.degrees(math.atan(4.9*k)),-30,30)
    ff=math.degrees(math.atan(2.5*k))
    steer=clamp(ff+1.8*(h-hd),-43,43)
    speed=-0.75 if abs(h)<28 else -0.4
    return steer,speed,180

