import math
def interp(rail,u):
 for a,b in zip(rail,rail[1:]):
  if min(a[0],b[0])<=u<=max(a[0],b[0]) and abs(b[0]-a[0])>0.01:
   return a[1]+(b[1]-a[1])*(u-a[0])/(b[0]-a[0])
 return None
def control(o):
 lm=o['local_map']
 u=10.5
 a=interp(lm['left_rail'],u); b=interp(lm['right_rail'],u)
 if a is None or b is None:
  bearing=math.radians(o['route']['bearing_deg'])
  u=10*math.cos(bearing); v=10*math.sin(bearing)
 else: v=(a+b)/2
 k=2*v/max(16,u*u+v*v)
 hd=max(-42,min(42,math.degrees(math.atan(10.2*k))))
 h=o['hitch_deg']
 steer=max(-42,min(42,math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))+1.5*(h-hd)))
 return (steer,-1.0,180)

